1	'use client';
2	
3	import { useState, useMemo, useEffect } from 'react';
4	import {
5	  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ReferenceLine, ResponsiveContainer,
6	} from 'recharts';
7	import {
8	  Users, Clock, TrendingUp, AlertTriangle, Star, ExternalLink,
9	  CheckCircle, XCircle, Activity, Database,
10	} from 'lucide-react';
11	import { facility as dummyFacility, shiftsByDate as dummyShiftsByDate, trendDates as dummyTrendDates, TODAY } from '@/lib/dummyData';
12	import {
13	  calculateDayCompliance,
14	  calculatePeriodCompliance,
15	  formatAUD,
16	  formatPct,
17	} from '@/lib/compliance';
18	import { getShifts, mapShift } from '@/lib/db';
19	import { SEED_FACILITY_ID } from '@/lib/seedData';
20	
21	// ─── Helpers ─────────────────────────────────────────────────────────────────
22	
23	function formatDate(isoDate) {
24	  const [y, m, d] = isoDate.split('-');
25	  return `${d}/${m}/${y}`;
26	}
27	
28	function ragColour(status) {
29	  if (status === 'GREEN') return '#22c55e';
30	  if (status === 'AMBER') return '#f59e0b';
31	  return '#ef4444';
32	}
33	
34	function ragBg(status) {
35	  if (status === 'GREEN') return 'bg-green-100 text-green-800';
36	  if (status === 'AMBER') return 'bg-amber-100 text-amber-800';
37	  return 'bg-red-100 text-red-800';
38	}
39	
40	// ─── Sub-components ───────────────────────────────────────────────────────────
41	
42	function StatCard({ title, value, sub, icon: Icon, iconColour, gradientClass }) {
43	  return (
44	    <div className={`rounded-xl shadow-sm border border-gray-100 p-4 md:p-5 card-hover cursor-default ${gradientClass || 'bg-white'}`}>
45	      <div className="flex items-start justify-between">
46	        <div className="min-w-0 flex-1 pr-2">
47	          <p className="text-xs font-medium text-gray-500 uppercase tracking-wide leading-tight">{title}</p>
48	          <p className="mt-1 text-xl md:text-2xl font-bold text-gray-900 truncate">{value}</p>
49	          {sub && <p className="mt-0.5 text-xs text-gray-500 truncate">{sub}</p>}
50	        </div>
51	        <div className={`p-2 rounded-lg shrink-0 ${iconColour}`}>
52	          <Icon className="w-4 h-4 md:w-5 md:h-5" />
53	        </div>
54	      </div>
55	    </div>
56	  );
57	}
58	
59	function ProgressBar({ pct, colour }) {
60	  const capped = Math.min(pct, 1);
61	  return (
62	    <div className="w-full bg-gray-100 rounded-full h-2.5 overflow-hidden">
63	      <div
64	        className="h-2.5 rounded-full"
65	        style={{
66	          width: `${capped * 100}%`,
67	          backgroundColor: colour,
68	          transition: 'width 0.8s cubic-bezier(0.4, 0, 0.2, 1)',
69	        }}
70	      />
71	    </div>
72	  );
73	}
74	
75	function StarRating({ rating }) {
76	  const full  = Math.floor(rating);
77	  const half  = rating % 1 >= 0.5 ? 1 : 0;
78	  const empty = 5 - full - half;
79	  return (
80	    <div className="flex items-center gap-0.5">
81	      {Array.from({ length: full }).map((_, i) => (
82	        <Star key={`f${i}`} className="w-5 h-5 fill-amber-400 text-amber-400" />
83	      ))}
84	      {half === 1 && (
85	        <span className="relative w-5 h-5">
86	          <Star className="w-5 h-5 text-gray-200 absolute" />
87	          <span className="absolute left-0 top-0 overflow-hidden w-1/2">
88	            <Star className="w-5 h-5 fill-amber-400 text-amber-400" />
89	          </span>
90	        </span>
91	      )}
92	      {Array.from({ length: empty }).map((_, i) => (
93	        <Star key={`e${i}`} className="w-5 h-5 text-gray-200" />
94	      ))}
95	    </div>
96	  );
97	}
98	
99	function TrendTooltip({ active, payload, label }) {
100	  if (!active || !payload || !payload.length) return null;
101	  const pct = payload[0]?.value;
102	  const status = pct >= 100 ? 'GREEN' : pct >= 85 ? 'AMBER' : 'RED';
103	  return (
104	    <div className="bg-white border border-gray-200 rounded-lg shadow-lg p-3 text-xs">
105	      <p className="font-semibold text-gray-700 mb-1">{label}</p>
106	      <p className="font-bold" style={{ color: ragColour(status) }}>
107	        {pct?.toFixed(1)}% compliance
108	      </p>
109	      <p className={`mt-0.5 inline-block px-1.5 py-0.5 rounded text-[10px] font-medium ${ragBg(status)}`}>
110	        {status}
111	      </p>
112	    </div>
113	  );
114	}
115	
116	// ─── Page ─────────────────────────────────────────────────────────────────────
117	
118	export default function DashboardPage() {
119	  const [dbShifts, setDbShifts]       = useState(null); // null = loading, [] = no data
120	  const [usingDb,  setUsingDb]        = useState(false);
121	  const [anAccRate]                   = useState(dummyFacility.anAccRate);
122	
123	  // Load shifts from Supabase — fall back to dummy data if error
124	  useEffect(() => {
125	    async function load() {
126	      const thirtyDaysAgo = new Date();
127	      thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
128	      const startDate = thirtyDaysAgo.toISOString().split('T')[0];
129	
130	      const { data, error } = await getShifts(SEED_FACILITY_ID, startDate);
131	      if (error || !data || data.length === 0) {
132	        setDbShifts(null); // use dummy
133	        setUsingDb(false);
134	      } else {
135	        setDbShifts(data.map(mapShift));
136	        setUsingDb(true);
137	      }
138	    }
139	    load();
140	  }, []);
141	
142	  // Decide data source
143	  const activeShiftsByDate = useMemo(() => {
144	    if (!dbShifts) return dummyShiftsByDate;
145	    return dbShifts.reduce((acc, sh) => {
146	      if (!acc[sh.date]) acc[sh.date] = [];
147	      acc[sh.date].push(sh);
148	      return acc;
149	    }, {});
150	  }, [dbShifts]);
151	
152	  const activeTrendDates = useMemo(() => {
153	    if (!dbShifts) return dummyTrendDates;
154	    const dates = [...new Set(dbShifts.map(s => s.date))].sort();
155	    return dates.slice(-30);
156	  }, [dbShifts]);
157	
158	  // Today's compliance
159	  const todayShifts = activeShiftsByDate[TODAY] || [];
160	  const todayData   = useMemo(() => calculateDayCompliance(todayShifts, dummyFacility.residentCount), [todayShifts]);
161	
162	  // 30-day period compliance
163	  const periodData = useMemo(() => {
164	    const daily = activeTrendDates.map(date => ({ date, shifts: activeShiftsByDate[date] || [] }));
165	    return calculatePeriodCompliance(daily, dummyFacility.residentCount);
166	  }, [activeTrendDates, activeShiftsByDate]);
167	
168	  // 30-day trend chart data
169	  const trendChartData = useMemo(() =>
170	    periodData.days.map(d => ({
171	      date:       formatDate(d.date),
172	      compliance: parseFloat((d.compliancePct * 100).toFixed(1)),
173	      status:     d.ragStatus,
174	    })),
175	  [periodData]);
176	
177	  // Staff breakdown for today
178	  const staffBreakdown = useMemo(() => {
179	    const agency  = todayShifts.filter(s => s.employmentType === 'Agency');
180	    const byType  = (type) => todayShifts.filter(s => s.staffType === type).reduce((a, s) => a + s.durationMinutes, 0);
181	    return {
182	      rn:     byType('RN'),
183	      en:     byType('EN'),
184	      pcw:    byType('PCW'),
185	      agency: agency.reduce((a, s) => a + s.durationMinutes, 0),
186	    };
187	  }, [todayShifts]);
188	
189	  // AN-ACC subsidy
190	  const totalDailySubsidy = dummyFacility.residentCount * anAccRate;
191	  const amountProtected   = todayData.isCompliant ? totalDailySubsidy : 0;
192	  const amountAtRisk      = !todayData.isCompliant ? totalDailySubsidy : 0;
193	
194	  const complianceRate14 = periodData.overallCompliancePct;
195	  const penaltyAtRisk14  = periodData.totalPenalty;
196	  const todayShiftCount  = todayShifts.length;
197	
198	  return (
199	    <div className="p-4 md:p-6 max-w-7xl mx-auto">
200	
201	      {/* ── Header ── */}
202	      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-6">
203	        <div>
204	          <div className="flex items-center gap-2 flex-wrap">
205	            <h1 className="text-xl font-bold text-gray-900">{dummyFacility.name}</h1>
206	            <span className="px-2 py-0.5 bg-blue-100 text-blue-700 text-xs font-semibold rounded-full border border-blue-200">
207	              DEMO MODE
208	            </span>
209	            {usingDb && (
210	              <span className="flex items-center gap-1 px-2 py-0.5 bg-green-100 text-green-700 text-xs font-semibold rounded-full border border-green-200">
211	                <Database className="w-3 h-3" /> Live DB
212	              </span>
213	            )}
214	          </div>
215	          <p className="text-sm text-gray-500 mt-0.5">{formatDate(TODAY)} · {dummyFacility.state}</p>
216	        </div>
217	        <div className={`flex items-center gap-2 px-3 py-2 rounded-lg font-medium text-sm shrink-0 ${
218	          todayData.isCompliant ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
219	        }`}>
220	          {todayData.isCompliant
221	            ? <><CheckCircle className="w-4 h-4" /> Compliant Today</>
222	            : <><XCircle className="w-4 h-4" /> Non-Compliant Today</>
223	          }
224	        </div>
225	      </div>
226	
227	      {/* ── 4 Quick Stat Cards ── */}
228	      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 md:gap-4 mb-6">
229	        <StatCard
230	          title="Residents in Care"
231	          value={dummyFacility.residentCount}
232	          sub="Today"
233	          icon={Users}
234	          iconColour="bg-blue-100 text-blue-600"
235	          gradientClass="stat-gradient-blue"
236	        />
237	        <StatCard
238	          title="Shifts Logged"
239	          value={todayShiftCount}
240	          sub={`${todayShifts.reduce((a, s) => a + s.durationMinutes, 0).toLocaleString()} min total`}
241	          icon={Clock}
242	          iconColour="bg-purple-100 text-purple-600"
243	          gradientClass="stat-gradient-purple"
244	        />
245	        <StatCard
246	          title="30-Day Compliance"
247	          value={formatPct(complianceRate14)}
248	          sub={`${periodData.compliantDays}/${periodData.totalDays} days compliant`}
249	          icon={TrendingUp}
250	          iconColour={`${complianceRate14 >= 1 ? 'bg-green-100 text-green-600' : complianceRate14 >= 0.85 ? 'bg-amber-100 text-amber-600' : 'bg-red-100 text-red-600'}`}
251	          gradientClass={complianceRate14 >= 1 ? 'stat-gradient-green' : complianceRate14 >= 0.85 ? 'stat-gradient-amber' : 'stat-gradient-red'}
252	        />
253	        <StatCard
254	          title="Penalty at Risk"
255	          value={formatAUD(penaltyAtRisk14)}
256	          sub="Last 30 days"
257	          icon={AlertTriangle}
258	          iconColour={penaltyAtRisk14 > 0 ? 'bg-red-100 text-red-600' : 'bg-green-100 text-green-600'}
259	          gradientClass={penaltyAtRisk14 > 0 ? 'stat-gradient-red' : 'stat-gradient-green'}
260	        />
261	      </div>
262	
263	      <div className="grid grid-cols-1 xl:grid-cols-3 gap-4 md:gap-6">
264	
265	        {/* ── Left column (2/3) ── */}
266	        <div className="xl:col-span-2 space-y-4 md:space-y-6">
267	
268	          {/* Today's Compliance Card */}
269	          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 md:p-5 card-hover">
270	            <div className="flex items-center justify-between mb-4">
271	              <h2 className="font-semibold text-gray-900">Today's Compliance</h2>
272	              <span className={`px-2.5 py-1 rounded-full text-xs font-bold ${ragBg(todayData.ragStatus)}`}>
273	                {todayData.ragStatus}
274	              </span>
275	            </div>
276	
277	            <div className="mb-4">
278	              <div className="flex justify-between items-end mb-1.5 gap-2">
279	                <span className="text-sm text-gray-600 shrink-0">Total Care Minutes</span>
280	                <span className="text-sm font-semibold text-gray-900 text-right">
281	                  {todayData.totalMinutes.toLocaleString()} / {todayData.targetMinutes.toLocaleString()} min
282	                </span>
283	              </div>
284	              <ProgressBar pct={todayData.compliancePct} colour={ragColour(todayData.ragStatus)} />
285	              <div className="flex justify-between mt-1 gap-2">
286	                <span className="text-xs text-gray-400">{formatPct(todayData.compliancePct)} of daily target</span>
287	                {todayData.minutesGap > 0 && (
288	                  <span className="text-xs text-red-500 font-medium">{todayData.minutesGap.toLocaleString()} min short</span>
289	                )}
290	              </div>
291	            </div>
292	
293	            <div className="mb-4">
294	              <div className="flex justify-between items-end mb-1.5 gap-2">
295	                <span className="text-sm text-gray-600 shrink-0">RN Minutes</span>
296	                <span className="text-sm font-semibold text-gray-900 text-right">
297	                  {todayData.rnMinutes.toLocaleString()} / {todayData.rnTargetMinutes.toLocaleString()} min
298	                </span>
299	              </div>
300	              <ProgressBar pct={todayData.rnCompliancePct} colour={ragColour(todayData.rnRagStatus)} />
301	              <div className="flex justify-between mt-1 gap-2">
302	                <span className="text-xs text-gray-400">{formatPct(todayData.rnCompliancePct)} of RN target</span>
303	                {todayData.rnMinutesGap > 0 && (
304	                  <span className="text-xs text-amber-600 font-medium">{todayData.rnMinutesGap.toLocaleString()} min RN gap</span>
305	                )}
306	              </div>
307	            </div>
308	
309	            {todayData.ragStatus === 'RED' && (
310	              <div className="bg-red-50 border border-red-200 rounded-lg p-3 mb-4">
311	                <p className="text-sm text-red-700 font-medium">
312	                  ⚠ {todayData.minutesGap.toLocaleString()} minutes short of today's target.
313	                  Add {Math.ceil(todayData.minutesGap / 480)} additional shift{Math.ceil(todayData.minutesGap / 480) !== 1 ? 's' : ''} to become compliant.
314	                </p>
315	              </div>
316	            )}
317	            {todayData.ragStatus === 'AMBER' && (
318	              <div className="bg-amber-50 border border-amber-200 rounded-lg p-3 mb-4">
319	                <p className="text-sm text-amber-700 font-medium">
320	                  ⚠ {todayData.minutesGap.toLocaleString()} minutes below target — no penalty yet but at risk.
321	                  Reach 100% to secure full compliance.
322	                </p>
323	              </div>
324	            )}
325	
326	            <div className={`flex items-center justify-between rounded-lg p-3 gap-2 ${
327	              todayData.ragStatus === 'RED'   ? 'bg-red-50 border border-red-200' :
328	              todayData.ragStatus === 'AMBER' ? 'bg-amber-50 border border-amber-200' :
329	                                                'bg-green-50 border border-green-200'
330	            }`}>
331	              <span className={`text-sm font-medium ${
332	                todayData.ragStatus === 'RED'   ? 'text-red-700' :
333	                todayData.ragStatus === 'AMBER' ? 'text-amber-700' :
334	                                                  'text-green-700'
335	              }`}>
336	                Penalty at risk today
337	              </span>
338	              <span className={`text-sm font-bold shrink-0 ${
339	                todayData.ragStatus === 'RED'   ? 'text-red-700' :
340	                todayData.ragStatus === 'AMBER' ? 'text-amber-700' :
341	                                                  'text-green-700'
342	              }`}>
343	                {todayData.ragStatus === 'RED'   ? formatAUD(todayData.penaltyAmount) :
344	                 todayData.ragStatus === 'AMBER' ? formatAUD(0) :
345	                                                   'None — compliant ✓'}
346	              </span>
347	            </div>
348	          </div>
349	
350	          {/* 30-Day Trend Chart */}
351	          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 md:p-5 card-hover">
352	            <h2 className="font-semibold text-gray-900 mb-4">30-Day Compliance Trend</h2>
353	            <div className="h-56 md:h-64">
354	              <ResponsiveContainer width="100%" height="100%">
355	                <LineChart data={trendChartData} margin={{ top: 5, right: 10, left: -20, bottom: 5 }}>
356	                  <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" />
357	                  <XAxis
358	                    dataKey="date"
359	                    tick={{ fontSize: 9, fill: '#94a3b8' }}
360	                    tickLine={false}
361	                    axisLine={false}
362	                    interval={1}
363	                  />
364	                  <YAxis
365	                    domain={[60, 120]}
366	                    tick={{ fontSize: 9, fill: '#94a3b8' }}
367	                    tickLine={false}
368	                    axisLine={false}
369	                    tickFormatter={v => `${v}%`}
370	                  />
371	                  <Tooltip content={<TrendTooltip />} />
372	                  <ReferenceLine y={100} stroke="#22c55e" strokeDasharray="4 4" strokeWidth={1.5} label={{ value: '100%', fill: '#22c55e', fontSize: 9, position: 'right' }} />
373	                  <ReferenceLine y={85}  stroke="#f59e0b" strokeDasharray="4 4" strokeWidth={1.5} label={{ value: '85%', fill: '#f59e0b', fontSize: 9, position: 'right' }} />
374	                  <Line
375	                    type="monotone"
376	                    dataKey="compliance"
377	                    stroke="#3b82f6"
378	                    strokeWidth={2}
379	                    dot={(props) => {
380	                      const { cx, cy, payload } = props;
381	                      const colour = ragColour(payload.status);
382	                      return <circle key={cx} cx={cx} cy={cy} r={4} fill={colour} stroke="white" strokeWidth={2} />;
383	                    }}
384	                    activeDot={{ r: 6 }}
385	                  />
386	                </LineChart>
387	              </ResponsiveContainer>
388	            </div>
389	            <div className="flex items-center gap-3 mt-2 text-xs text-gray-500 flex-wrap">
390	              <span className="flex items-center gap-1"><span className="w-2.5 h-2.5 rounded-full bg-[#22c55e] inline-block" /> Compliant</span>
391	              <span className="flex items-center gap-1"><span className="w-2.5 h-2.5 rounded-full bg-[#f59e0b] inline-block" /> At risk</span>
392	              <span className="flex items-center gap-1"><span className="w-2.5 h-2.5 rounded-full bg-[#ef4444] inline-block" /> Non-compliant</span>
393	            </div>
394	          </div>
395	
396	          {/* Staff Breakdown */}
397	          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 md:p-5 card-hover">
398	            <h2 className="font-semibold text-gray-900 mb-4">Today's Staff Breakdown</h2>
399	            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
400	              {[
401	                { label: 'RN Minutes',     value: staffBreakdown.rn,     colour: '#3b82f6', bg: 'bg-blue-50',   border: 'border-blue-100'   },
402	                { label: 'EN Minutes',     value: staffBreakdown.en,     colour: '#8b5cf6', bg: 'bg-purple-50', border: 'border-purple-100' },
403	                { label: 'PCW Minutes',    value: staffBreakdown.pcw,    colour: '#22c55e', bg: 'bg-green-50',  border: 'border-green-100'  },
404	                { label: 'Agency Minutes', value: staffBreakdown.agency, colour: '#f59e0b', bg: 'bg-amber-50',  border: 'border-amber-100'  },
405	              ].map(({ label, value, colour, bg, border }) => (
406	                <div key={label} className={`${bg} border ${border} rounded-lg p-3 card-hover`}>
407	                  <p className="text-xs text-gray-500 mb-1 font-medium">{label}</p>
408	                  <p className="text-lg md:text-xl font-bold" style={{ color: colour }}>{value.toLocaleString()}</p>
409	                  <p className="text-xs text-gray-400 mt-0.5">{Math.floor(value/60)}h {value%60}m</p>
410	                </div>
411	              ))}
412	            </div>
413	          </div>
414	        </div>
415	
416	        {/* ── Right column (1/3) ── */}
417	        <div className="space-y-4 md:space-y-6">
418	
419	          {/* AN-ACC Subsidy */}
420	          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 md:p-5 card-hover">
421	            <div className="flex items-center gap-2 mb-4">
422	              <div className="p-1.5 rounded-lg bg-blue-50">
423	                <Activity className="w-3.5 h-3.5 text-blue-600" />
424	              </div>
425	              <h2 className="font-semibold text-gray-900">AN-ACC Subsidy</h2>
426	            </div>
427	            <div className="space-y-3">
428	              <div className="flex justify-between text-sm">
429	                <span className="text-gray-500">Rate per resident</span>
430	                <span className="font-medium text-gray-900">{formatAUD(anAccRate)}/day</span>
431	              </div>
432	              <div className="flex justify-between text-sm">
433	                <span className="text-gray-500">Total daily subsidy</span>
434	                <span className="font-bold text-gray-900">{formatAUD(totalDailySubsidy)}</span>
435	              </div>
436	              <hr className="border-gray-100" />
437	              <div className="flex justify-between text-sm">
438	                <span className="text-gray-500">Amount protected</span>
439	                <span className="font-semibold text-green-600">{formatAUD(amountProtected)}</span>
440	              </div>
441	              <div className="flex justify-between text-sm">
442	                <span className="text-gray-500">Amount at risk</span>
443	                <span className={`font-semibold ${amountAtRisk > 0 ? 'text-red-600' : 'text-gray-400'}`}>
444	                  {amountAtRisk > 0 ? formatAUD(amountAtRisk) : '$0.00'}
445	                </span>
446	              </div>
447	            </div>
448	          </div>
449	
450	          {/* Star Rating — temporarily hidden
451	          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 md:p-5 card-hover">
452	            <div className="flex items-center gap-2 mb-4">
453	              <div className="p-1.5 rounded-lg bg-amber-50">
454	                <Star className="w-3.5 h-3.5 text-amber-500" />
455	              </div>
456	              <h2 className="font-semibold text-gray-900">Star Rating</h2>
457	            </div>
458	            <div className="flex items-center gap-3 mb-3">
459	              <StarRating rating={dummyFacility.starRating} />
460	              <span className="text-2xl font-bold text-gray-900">{dummyFacility.starRating}</span>
461	              <span className="text-sm text-gray-400">/ 5</span>
462	            </div>
463	            {complianceRate14 < 1 && (
464	              <div className="bg-amber-50 border border-amber-200 rounded-lg p-3 mb-3">
465	                <p className="text-xs text-amber-700">
466	                  ⚠ Compliance below 100% may affect your star rating on MyAgedCare.
467	                </p>
468	              </div>
469	            )}
470	            <a
471	              href="https://www.myagedcare.gov.au"
472	              target="_blank"
473	              rel="noopener noreferrer"
474	              className="flex items-center gap-1.5 text-xs text-blue-600 hover:text-blue-800 font-medium transition-colors"
475	            >
476	              <ExternalLink className="w-3 h-3" />
