1	/**
2	 * CareMinutes.ai — Compliance Calculator
3	 *
4	 * Implements Australian Government aged care regulations (from April 2026):
5	 *   - Every resident must receive 215 minutes of care per day (averaged across all residents)
6	 *   - Of those 215 minutes, at least 44 must come from a Registered Nurse (RN)
7	 *   - Staff types that count toward total: RN, EN, PCW, Agency
8	 *   - Only RN time counts toward the 44-minute RN minimum
9	 *   - Penalty: $31.64 AUD per resident per day for non-compliant days
10	 *
11	 * RAG thresholds:
12	 *   - RED    = below 85% of target
13	 *   - AMBER  = 85% to 99% of target (inclusive)
14	 *   - GREEN  = 100% or above target
15	 *
16	 * CRITICAL: This logic directly affects government funding calculations.
17	 * All edge cases are handled. Do not modify without thorough testing.
18	 */
19	
20	/** Daily care minutes target per resident */
21	export const DAILY_MINUTES_PER_RESIDENT = 215;
22	
23	/** Minimum RN minutes required per resident per day */
24	export const RN_MINUTES_PER_RESIDENT = 44;
25	
26	/** Penalty per resident per non-compliant day (AUD) */
27	export const PENALTY_PER_RESIDENT_PER_DAY = 31.64;
28	
29	/** RAG threshold — below this percentage = RED */
30	export const RED_THRESHOLD = 0.85;
31	
32	/** RAG threshold — at or above this percentage = GREEN */
33	export const GREEN_THRESHOLD = 1.0;
34	
35	/**
36	 * Determines the RAG (Red/Amber/Green) status for a given compliance percentage.
37	 *
38	 * @param {number} compliancePct - Compliance as a decimal (e.g. 0.92 = 92%)
39	 * @returns {'GREEN'|'AMBER'|'RED'}
40	 */
41	export function getRAGStatus(compliancePct) {
42	  if (compliancePct >= GREEN_THRESHOLD) return 'GREEN';
43	  if (compliancePct >= RED_THRESHOLD) return 'AMBER';
44	  return 'RED';
45	}
46	
47	/**
48	 * Determines the RAG status specifically for RN minutes compliance.
49	 * Uses the same thresholds applied to the RN minimum (44 min/resident).
50	 *
51	 * @param {number} rnPct - RN compliance as a decimal
52	 * @returns {'GREEN'|'AMBER'|'RED'}
53	 */
54	export function getRNRAGStatus(rnPct) {
55	  return getRAGStatus(rnPct);
56	}
57	
58	/**
59	 * Calculates compliance for a single day.
60	 *
61	 * @param {Array<{staffType: string, durationMinutes: number}>} shifts
62	 *   Array of shift objects. staffType must be one of: 'RN', 'EN', 'PCW', 'Agency'.
63	 *   durationMinutes is the length of the shift in minutes.
64	 * @param {number} residentCount - Number of residents in the facility that day.
65	 * @returns {{
66	 *   totalMinutes: number,
67	 *   rnMinutes: number,
68	 *   enMinutes: number,
69	 *   pcwMinutes: number,
70	 *   agencyMinutes: number,
71	 *   targetMinutes: number,
72	 *   rnTargetMinutes: number,
73	 *   compliancePct: number,
74	 *   rnCompliancePct: number,
75	 *   ragStatus: 'GREEN'|'AMBER'|'RED',
76	 *   rnRagStatus: 'GREEN'|'AMBER'|'RED',
77	 *   isCompliant: boolean,
78	 *   isRNCompliant: boolean,
79	 *   penaltyAmount: number,
80	 *   minutesGap: number,
81	 *   rnMinutesGap: number,
82	 * }}
83	 */
84	export function calculateDayCompliance(shifts, residentCount) {
85	  // Edge case: no residents — compliance is undefined, treat as non-compliant
86	  if (!residentCount || residentCount <= 0) {
87	    return {
88	      totalMinutes: 0,
89	      rnMinutes: 0,
90	      enMinutes: 0,
91	      pcwMinutes: 0,
92	      agencyMinutes: 0,
93	      targetMinutes: 0,
94	      rnTargetMinutes: 0,
95	      compliancePct: 0,
96	      rnCompliancePct: 0,
97	      ragStatus: 'RED',
98	      rnRagStatus: 'RED',
99	      isCompliant: false,
100	      isRNCompliant: false,
101	      penaltyAmount: 0,
102	      minutesGap: 0,
103	      rnMinutesGap: 0,
104	    };
105	  }
106	
107	  // Edge case: no shifts logged — zero minutes delivered
108	  const safeShifts = Array.isArray(shifts) ? shifts : [];
109	
110	  // Tally minutes by staff type
111	  let rnMinutes = 0;
112	  let enMinutes = 0;
113	  let pcwMinutes = 0;
114	  let agencyMinutes = 0;
115	
116	  for (const shift of safeShifts) {
117	    const duration = Number(shift.durationMinutes) || 0;
118	    const type = (shift.staffType || '').toUpperCase();
119	
120	    switch (type) {
121	      case 'RN':
122	        rnMinutes += duration;
123	        break;
124	      case 'EN':
125	        enMinutes += duration;
126	        break;
127	      case 'PCW':
128	        pcwMinutes += duration;
129	        break;
130	      case 'AGENCY RN':
131	        // Agency-sourced RN — counts as both RN time AND agency time
132	        rnMinutes += duration;
133	        agencyMinutes += duration;
134	        break;
135	      case 'AGENCY':
136	        // Agency-sourced non-RN staff — counts toward total, tracked separately
137	        agencyMinutes += duration;
138	        break;
139	      // Unknown staff types are excluded from compliance counting
140	    }
141	  }
142	
143	  // Total care minutes: RN + EN + PCW + Agency all count
144	  const totalMinutes = rnMinutes + enMinutes + pcwMinutes + agencyMinutes;
145	
146	  // Daily targets based on resident count
147	  const targetMinutes = residentCount * DAILY_MINUTES_PER_RESIDENT;
148	  const rnTargetMinutes = residentCount * RN_MINUTES_PER_RESIDENT;
149	
150	  // Compliance percentages (capped at 2 decimal places for display)
151	  const compliancePct = targetMinutes > 0 ? totalMinutes / targetMinutes : 0;
152	  const rnCompliancePct = rnTargetMinutes > 0 ? rnMinutes / rnTargetMinutes : 0;
153	
154	  // RAG status
155	  const ragStatus = getRAGStatus(compliancePct);
156	  const rnRagStatus = getRNRAGStatus(rnCompliancePct);
157	
158	  // A day is compliant only if BOTH total AND RN minimums are met
159	  const isCompliant = compliancePct >= GREEN_THRESHOLD;
160	  const isRNCompliant = rnCompliancePct >= GREEN_THRESHOLD;
161	
162	  // Penalty applies ONLY on RED days (below 85% of target).
163	  // AMBER days (85–99%) are at risk but do NOT incur a financial penalty.
164	  // GREEN days (100%+) are fully compliant — no penalty.
165	  const penaltyAmount = ragStatus === 'RED' ? residentCount * PENALTY_PER_RESIDENT_PER_DAY : 0;
166	
167	  // Gaps (negative means surplus, positive means shortfall)
168	  const minutesGap = targetMinutes - totalMinutes;
169	  const rnMinutesGap = rnTargetMinutes - rnMinutes;
170	
171	  return {
172	    totalMinutes,
173	    rnMinutes,
174	    enMinutes,
175	    pcwMinutes,
176	    agencyMinutes,
177	    targetMinutes,
178	    rnTargetMinutes,
179	    compliancePct,
180	    rnCompliancePct,
181	    ragStatus,
182	    rnRagStatus,
183	    isCompliant,
184	    isRNCompliant,
185	    penaltyAmount,
186	    minutesGap,
187	    rnMinutesGap,
188	  };
189	}
190	
191	/**
192	 * Calculates compliance across a period (e.g. 14 days, a quarter).
193	 *
194	 * @param {Array<{date: string, shifts: Array}>} dailyData
195	 *   Array of day objects, each with a date string and shifts array.
196	 * @param {number} residentCount - Number of residents (assumed constant over period).
197	 * @returns {{
198	 *   days: Array,           — per-day compliance results with date attached
199	 *   totalDays: number,
200	 *   compliantDays: number,
201	 *   nonCompliantDays: number,
202	 *   overallCompliancePct: number,
203	 *   totalPenalty: number,
204	 *   averageDailyMinutes: number,
205	 *   averageRNMinutes: number,
206	 * }}
207	 */
208	export function calculatePeriodCompliance(dailyData, residentCount) {
209	  if (!Array.isArray(dailyData) || dailyData.length === 0) {
210	    return {
211	      days: [],
212	      totalDays: 0,
213	      compliantDays: 0,
214	      nonCompliantDays: 0,
215	      overallCompliancePct: 0,
216	      totalPenalty: 0,
217	      averageDailyMinutes: 0,
218	      averageRNMinutes: 0,
219	    };
220	  }
221	
222	  const days = dailyData.map((day) => {
223	    const result = calculateDayCompliance(day.shifts, residentCount);
224	    return {
225	      date: day.date,
226	      ...result,
227	    };
228	  });
229	
230	  const totalDays = days.length;
231	  const compliantDays = days.filter((d) => d.isCompliant).length;
232	  const nonCompliantDays = totalDays - compliantDays;
233	
234	  // Overall compliance % = compliant days / total days
235	  const overallCompliancePct = totalDays > 0 ? compliantDays / totalDays : 0;
236	
237	  const totalPenalty = days.reduce((sum, d) => sum + d.penaltyAmount, 0);
238	
239	  const totalMinutesSum = days.reduce((sum, d) => sum + d.totalMinutes, 0);
240	  const totalRNMinutesSum = days.reduce((sum, d) => sum + d.rnMinutes, 0);
241	
242	  const averageDailyMinutes = totalDays > 0 ? totalMinutesSum / totalDays : 0;
243	  const averageRNMinutes = totalDays > 0 ? totalRNMinutesSum / totalDays : 0;
244	
245	  return {
246	    days,
247	    totalDays,
248	    compliantDays,
249	    nonCompliantDays,
250	    overallCompliancePct,
251	    totalPenalty,
252	    averageDailyMinutes,
253	    averageRNMinutes,
254	  };
255	}
256	
257	/**
258	 * Projects the total penalty for a quarter based on current pace.
259	 *
260	 * Formula from ACQSC guidelines:
261	 *   projected penalty = accrued penalty + (daily non-compliance rate × days remaining × daily penalty)
262	 *
263	 * @param {{
264	 *   days: Array,
265	 *   totalPenalty: number,
266	 *   nonCompliantDays: number,
267	 *   totalDays: number,
268	 * }} periodData - Result from calculatePeriodCompliance for days elapsed so far.
269	 * @param {number} residentCount
270	 * @param {number} daysRemaining - Number of days left in the quarter.
271	 * @returns {{
272	 *   accruedPenalty: number,
273	 *   projectedAdditionalPenalty: number,
274	 *   projectedTotalPenalty: number,
275	 *   dailyPenaltyRate: number,
276	 *   nonComplianceRate: number,
277	 * }}
278	 */
279	export function projectQuarterPenalty(periodData, residentCount, daysRemaining) {
280	  if (!periodData || periodData.totalDays === 0) {
281	    return {
282	      accruedPenalty: 0,
283	      projectedAdditionalPenalty: 0,
284	      projectedTotalPenalty: 0,
285	      dailyPenaltyRate: 0,
286	      nonComplianceRate: 0,
287	    };
288	  }
289	
290	  const accruedPenalty = periodData.totalPenalty;
291	
292	  // Expected penalty per day at current pace
293	  const dailyPenaltyRate = residentCount * PENALTY_PER_RESIDENT_PER_DAY;
294	
295	  // Penalty rate = fraction of days that actually incurred a penalty (RED days only).
296	  // Derived from accrued penalty rather than nonCompliantDays so that AMBER days
297	  // (which have penaltyAmount = 0) do not inflate the projected penalty.
298	  const nonComplianceRate = (periodData.totalDays > 0 && dailyPenaltyRate > 0)
299	    ? periodData.totalPenalty / (periodData.totalDays * dailyPenaltyRate)
300	    : 0;
301	
302	  // Projected additional penalty for remaining days at current RED-day rate
303	  const projectedAdditionalPenalty = nonComplianceRate * daysRemaining * dailyPenaltyRate;
304	
305	  const projectedTotalPenalty = accruedPenalty + projectedAdditionalPenalty;
306	
307	  return {
308	    accruedPenalty,
309	    projectedAdditionalPenalty,
310	    projectedTotalPenalty,
311	    dailyPenaltyRate,
312	    nonComplianceRate,
313	  };
314	}
315	
316	/**
317	 * Calculates how many additional minutes per day are needed for the
318	 * remaining days of the quarter to achieve full compliance.
319	 *
320	 * Used in the "Recovery Plan" card on the Forecast page.
321	 *
322	 * @param {number} currentTotalMinutes - Total minutes delivered so far this quarter
323	 * @param {number} residentCount
324	 * @param {number} daysElapsed - Days already passed in the quarter
325	 * @param {number} daysRemaining - Days left in the quarter
326	 * @returns {{
327	 *   targetTotalMinutes: number,  — total target for full quarter
328	 *   shortfallMinutes: number,    — how many minutes still needed
329	 *   additionalMinutesPerDay: number, — extra minutes needed per remaining day
330	 *   isOnTrack: boolean,
331	 * }}
332	 */
333	export function calculateRecoveryPlan(
334	  currentTotalMinutes,
335	  residentCount,
336	  daysElapsed,
337	  daysRemaining
338	) {
339	  const totalDays = daysElapsed + daysRemaining;
340	  const targetTotalMinutes = residentCount * DAILY_MINUTES_PER_RESIDENT * totalDays;
341	
342	  const shortfallMinutes = Math.max(0, targetTotalMinutes - currentTotalMinutes);
343	
344	  const additionalMinutesPerDay = daysRemaining > 0
345	    ? shortfallMinutes / daysRemaining
346	    : 0;
347	
348	  const isOnTrack = shortfallMinutes === 0;
349	
350	  return {
351	    targetTotalMinutes,
352	    shortfallMinutes,
353	    additionalMinutesPerDay,
354	    isOnTrack,
355	  };
356	}
357	
358	/**
359	 * Calculates the impact of adding extra RN shifts per week on quarterly compliance.
360	 *
361	 * Used in the "What If" scenario tool on the Forecast page.
362	 *
363	 * @param {number} extraShiftsPerWeek - Number of extra RN shifts to add (1–10)
364	 * @param {number} shiftDurationMinutes - Average duration of each extra shift (default 480 = 8hr)
365	 * @param {number} daysRemaining - Days remaining in the quarter
366	 * @param {number} residentCount
367	 * @param {number} currentNonCompliantDays - Non-compliant days accrued so far
368	 * @param {number} currentTotalMinutes - Total minutes already delivered this quarter
369	 * @param {number} daysElapsed - Days elapsed in quarter so far
370	 * @returns {{
371	 *   additionalMinutesPerWeek: number,
372	 *   additionalMinutesPerDay: number,
373	 *   projectedCompliantDays: number,
374	 *   projectedNonCompliantDays: number,
375	 *   projectedCompliancePct: number,
376	 *   penaltySaved: number,
377	 * }}
378	 */
379	export function calculateWhatIfScenario(
380	  extraShiftsPerWeek,
381	  shiftDurationMinutes = 480,
382	  daysRemaining,
383	  residentCount,
384	  currentNonCompliantDays,
385	  currentTotalMinutes,
386	  daysElapsed
387	) {
388	  const additionalMinutesPerWeek = extraShiftsPerWeek * shiftDurationMinutes;
389	  const additionalMinutesPerDay = additionalMinutesPerWeek / 7;
390	
391	  const dailyTarget = residentCount * DAILY_MINUTES_PER_RESIDENT;
392	
393	  // Estimate how many of the remaining days would become compliant with the extra shifts
394	  // We base this on whether average daily minutes (improved) would meet target
395	  const currentAvgDaily = daysElapsed > 0 ? currentTotalMinutes / daysElapsed : 0;
396	  const improvedAvgDaily = currentAvgDaily + additionalMinutesPerDay;
397	
398	  // For remaining days: would the improved average meet target?
399	  const remainingCompliantDays = improvedAvgDaily >= dailyTarget ? daysRemaining : 0;
400	
401	  const totalDays = daysElapsed + daysRemaining;
402	  const projectedCompliantDays = Math.min(
403	    totalDays,
404	    (totalDays - currentNonCompliantDays - (daysRemaining - remainingCompliantDays))
405	  );
406	  const projectedNonCompliantDays = totalDays - projectedCompliantDays;
407	  const projectedCompliancePct = totalDays > 0 ? projectedCompliantDays / totalDays : 0;
408	
409	  // Penalty saved = days that become compliant × daily penalty
410	  const dailyPenalty = residentCount * PENALTY_PER_RESIDENT_PER_DAY;
411	  const penaltySaved = (daysRemaining - (daysRemaining - remainingCompliantDays)) * dailyPenalty;
412	
413	  return {
414	    additionalMinutesPerWeek,
415	    additionalMinutesPerDay,
416	    projectedCompliantDays: Math.max(0, projectedCompliantDays),
417	    projectedNonCompliantDays: Math.max(0, projectedNonCompliantDays),
418	    projectedCompliancePct: Math.min(1, Math.max(0, projectedCompliancePct)),
419	    penaltySaved: Math.max(0, penaltySaved),
420	  };
421	}
422	
423	/**
424	 * Formats a currency value as AUD.
425	 * @param {number} amount
426	 * @returns {string} e.g. "$1,265.60"
427	 */
428	export function formatAUD(amount) {
429	  return new Intl.NumberFormat('en-AU', {
430	    style: 'currency',
431	    currency: 'AUD',
432	    minimumFractionDigits: 2,
433	  }).format(amount);
434	}
435	
436	/**
437	 * Formats a compliance percentage for display.
438	 * @param {number} pct - Decimal (e.g. 0.92)
439	 * @returns {string} e.g. "92.0%"
440	 */
441	export function formatPct(pct) {
442	  return (pct * 100).toFixed(1) + '%';
443	}
