                    <div key={label} className="flex justify-between py-1 border-b border-gray-50 last:border-0 gap-2">
                      <span className="text-gray-500 shrink-0">{label}</span>
                      <span className={`font-semibold ${colour}`}>{value}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* What If Scenario */}
