// ── RAG colour helpers ────────────────────────────────────────────────────────

function ragColours(status) {
  if (status === 'GREEN')  return { bg: '#dcfce7', border: '#bbf7d0', text: '#15803d' };
  if (status === 'AMBER')  return { bg: '#fef3c7', border: '#fde68a', text: '#92400e' };
  return                          { bg: '#fee2e2', border: '#fecaca', text: '#991b1b' };
}

